describe('GET /shipments stays fresh and ordered (no ETA caching)', () => {
  let srv: TestServer;

  before(async () => {
    srv = await startTestServer();
  });

  after(async () => {
    await srv.close();
  });

  it('shows the new eta right after an exception event', async () => {
